window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-608a29904900c247"]={"versions": [{"id": "FIG-608a29904900c247", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Ressourcentemplate-Metamodells. Das Diagramm modelliert die strukturellen Eigenschaften und Assoziationen des allgemeinen Hardware-Elements (<code>HWElement</code>) und dessen physikalische sowie logische Schnittstellenanbindungen (<code>HWPort</code>, <code>HWPin</code>, <code>PowerSupplyHWPort</code>) sowie Umwelt- und Sicherheitsanforderungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>HWElement</strong> (<code>«ARElement»</code>, abstrakt/kursiv): Zentrales Hardware-Element mit dem optionalen Attribut <code>+ standbyCurrent: Float [0..1]</code>. Besitzt gerichtete Kompositionsbeziehungen zu:</li>\n<li><code>+ports</code> (Kardinalität <code>1..*</code>): Komposition von <code>HWPort</code>.</li>\n<li><code>+hwElementTemperature</code> (Rolle, Ziel-Kardinalität <code>0..1</code>): Komposition von <code>Temperature</code>.</li>\n<li><code>+supportsSafety</code> (Rolle, Ziel-Kardinalität <code>0..1</code>): Komposition von <code>SupportsSafety</code>.</li>\n<li><code>+supportsSecurity</code> (Rolle, Ziel-Kardinalität <code>0..1</code>): Komposition von <code>SupportsSecurity</code>.</li>\n<li>Gestrichelte gerichtete Abhängigkeit/Verwendung zu <code>PowerSupplyHWPort</code>.</li>\n<li><strong>HWPort</strong> (<code>«Identifiable»</code>): Repräsentiert einen Hardware-Port mit Attribut <code>+ direction: Enumeration{in, out, inout}</code>. Enthält per Komposition <code>+pins</code> (Kardinalität <code>*</code>) vom Typ <code>HWPin</code>.</li>\n<li><strong>HWPin</strong> (<code>«Identifiable»</code>): Repräsentiert einzelne Pins eines Ports.</li>\n<li><strong>PowerSupplyHWPort</strong>: Spezialisierung (<code>Generalization</code>) von <code>HWPort</code> mit dem Attribut <code>+ canBeSwitchedOff: Boolean [0..1]</code>.</li>\n<li><strong>Temperature</strong>: Strukturelement für Temperaturangaben mit den Attributen <code>+ operationMin: Int [0..1]</code>, <code>+ operationMax: Int [0..1]</code>, <code>+ operationTypical: Int [0..1]</code>, <code>+ storageMin: Int [0..1]</code>, <code>+ storageMax: Int [0..1]</code>, <code>+ needsCooling: Boolean [0..1]</code> und <code>+ needsHeating: Boolean [0..1]</code>.</li>\n<li><strong>SupportsSafety</strong>: Metamodell-Element zur Kennzeichnung unterstützter funktionaler Sicherheitsanforderungen.</li>\n<li><strong>SupportsSecurity</strong>: Metamodell-Element zur Kennzeichnung unterstützter IT-Sicherheitsanforderungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Abläufe oder Nachrichtensequenzen. Die Struktur definiert statische Kardinalitäten und Vererbungsbeziehungen für die deklarative Konfiguration von Hardware-Ressourcen im AUTOSAR-System.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>HWElement</code> muss mindestens einen <code>HWPort</code> aufweisen (<code>1..*</code>). Sämtliche Attribute (<code>standbyCurrent</code>, Temperaturwerte, Heiz-/Kühlbedarf sowie <code>canBeSwitchedOff</code>) sind optional (<code>[0..1]</code>). Die Vererbung von <code>Identifiable</code> durch <code>HWPort</code> und <code>HWPin</code> erfordert die Einhaltung standardisierter Benennungs- und Referenzierungskonventionen gemäß AUTOSAR-Metamodell-Regeln. Die Ausprägung von Sicherheits- und Security-Unterstützung sowie Umgebungsanforderungen erfolgt modular über optionale 0..1-Kompositionen.</p>"}, {"id": "FIG-1f273d1959511c1a", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Ressourcentemplate-Metamodells. Das Diagramm modelliert die strukturellen Eigenschaften und Assoziationen des allgemeinen Hardware-Elements (<code>HWElement</code>) und dessen physikalische sowie logische Schnittstellenanbindungen (<code>HWPort</code>, <code>HWPin</code>, <code>PowerSupplyHWPort</code>) sowie Umwelt- und Sicherheitsanforderungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>HWElement</strong> (<code>«ARElement»</code>, abstrakt/kursiv): Zentrales Hardware-Element mit dem optionalen Attribut <code>+ standbyCurrent: Float [0..1]</code>. Besitzt gerichtete Kompositionsbeziehungen zu:</li>\n<li><code>+ports</code> (Kardinalität <code>1..*</code>): Komposition von <code>HWPort</code>.</li>\n<li><code>+hwElementTemperature</code> (Rolle, Ziel-Kardinalität <code>0..1</code>): Komposition von <code>Temperature</code>.</li>\n<li><code>+supportsSafety</code> (Rolle, Ziel-Kardinalität <code>0..1</code>): Komposition von <code>SupportsSafety</code>.</li>\n<li><code>+supportsSecurity</code> (Rolle, Ziel-Kardinalität <code>0..1</code>): Komposition von <code>SupportsSecurity</code>.</li>\n<li>Gestrichelte gerichtete Abhängigkeit/Verwendung zu <code>PowerSupplyHWPort</code>.</li>\n<li><strong>HWPort</strong> (<code>«Identifiable»</code>): Repräsentiert einen Hardware-Port mit Attribut <code>+ direction: Enumeration{in, out, inout}</code>. Enthält per Komposition <code>+pins</code> (Kardinalität <code>*</code>) vom Typ <code>HWPin</code>.</li>\n<li><strong>HWPin</strong> (<code>«Identifiable»</code>): Repräsentiert einzelne Pins eines Ports.</li>\n<li><strong>PowerSupplyHWPort</strong>: Spezialisierung (<code>Generalization</code>) von <code>HWPort</code> mit dem Attribut <code>+ canBeSwitchedOff: Boolean [0..1]</code>.</li>\n<li><strong>Temperature</strong>: Strukturelement für Temperaturangaben mit den Attributen <code>+ operationMin: Int [0..1]</code>, <code>+ operationMax: Int [0..1]</code>, <code>+ operationTypical: Int [0..1]</code>, <code>+ storageMin: Int [0..1]</code>, <code>+ storageMax: Int [0..1]</code>, <code>+ needsCooling: Boolean [0..1]</code> und <code>+ needsHeating: Boolean [0..1]</code>.</li>\n<li><strong>SupportsSafety</strong>: Metamodell-Element zur Kennzeichnung unterstützter funktionaler Sicherheitsanforderungen.</li>\n<li><strong>SupportsSecurity</strong>: Metamodell-Element zur Kennzeichnung unterstützter IT-Sicherheitsanforderungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Abläufe oder Nachrichtensequenzen. Die Struktur definiert statische Kardinalitäten und Vererbungsbeziehungen für die deklarative Konfiguration von Hardware-Ressourcen im AUTOSAR-System.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>HWElement</code> muss mindestens einen <code>HWPort</code> aufweisen (<code>1..*</code>). Sämtliche Attribute (<code>standbyCurrent</code>, Temperaturwerte, Heiz-/Kühlbedarf sowie <code>canBeSwitchedOff</code>) sind optional (<code>[0..1]</code>). Die Vererbung von <code>Identifiable</code> durch <code>HWPort</code> und <code>HWPin</code> erfordert die Einhaltung standardisierter Benennungs- und Referenzierungskonventionen gemäß AUTOSAR-Metamodell-Regeln. Die Ausprägung von Sicherheits- und Security-Unterstützung sowie Umgebungsanforderungen erfolgt modular über optionale 0..1-Kompositionen.</p>"}], "trans": [{"from": "FIG-608a29904900c247", "to": "FIG-1f273d1959511c1a", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>PowerSupplyHWPort</strong>: Das Attribut <code>+ canBeSwitchedOff: Boolean [0..1]</code> ist am unteren Rand der Klasse durch das Zuschneiden der Bildhöhe (von 468 auf 419 Pixel) optisch abgeschnitten.</li>\n</ul>"}]};
